// ตรวจกำหนดเวลาที่ต้องดำเนินการ + สรุปสถานะปัจจุบัน
// ปลายทางจริง: /api/net/1x5/state (ข้อมูลจริงในฐานข้อมูล)
const s = $json || {};
const deadline = s.deadline || {};
const summary = s.summary || {};
const shouldRun = deadline.passed === true || summary.failed > 0;
return [{
  json: {
    workflow: '1x5 Autopilot 01 · deadline check',
    ok: s.ok !== false,
    period: s.period || null,
    deadlineISO: deadline.iso || null,
    daysLeft: typeof deadline.daysLeft === 'number' ? deadline.daysLeft : null,
    deadlinePassed: deadline.passed === true,
    pendingReview: summary.pendingReview || 0,
    failed: summary.failed || 0,
    vacancies: summary.vacancies || 0,
    readyCandidates: summary.readyCandidates || 0,
    shouldRunNow: shouldRun,
    idempotencyKey: 'net1x5-auto-' + (s.period || 'noperiod') + '-15m-' + new Date().toISOString().slice(0, 13),
    checkedAt: new Date().toISOString()
  }
}];

// สรุปผลการรันวงจรอัตโนมัติ (คัดออก → เลื่อนตำแหน่ง → จัดสายงาน → Log)
const r = $json || {};
const sm = r.summary || {};
const steps = Array.isArray(r.steps) ? r.steps.map(function (s) { return { step: s.step, label: s.label, count: s.count, status: s.status, detail: s.detail }; }) : [];
return [{ json: {
  workflow: '1x5 Autopilot 01 · apply result',
  ok: r.ok !== false,
  mode: r.mode || 'apply',
  runId: r.runId || null,
  period: r.period || null,
  cut: sm.cutLast || 0,
  promoted: sm.promotedLast || 0,
  vacancies: sm.vacancies || 0,
  readyCandidates: sm.readyCandidates || 0,
  steps: steps,
  warnings: r.warnings || [],
  note: 'ทุกการเปลี่ยนแปลงถูกบันทึกใน Audit Log + PlacementHistory + PlacementRun ตรวจสอบย้อนหลังได้',
  finishedAt: new Date().toISOString()
} }];
